import { useState, useEffect } from "react";
import { supabase } from "../lib/supabase";

export default function SubmissionsManager() {
  const [submissions, setSubmissions] = useState([]);
  const [loading, setLoading] = useState(true);
  const [selected, setSelected] = useState(null);
  const [msg, setMsg] = useState("");

  useEffect(() => { fetchSubmissions(); }, []);

  async function fetchSubmissions() {
    setLoading(true);
    const { data } = await supabase
      .from("submissions")
      .select("*")
      .order("created_at", { ascending: false });
    setSubmissions(data || []);
    setLoading(false);
  }

  function flash(text) {
    setMsg(text);
    setTimeout(() => setMsg(""), 3000);
  }

  async function markRead(id, current) {
    await supabase
      .from("submissions")
      .update({ read: !current })
      .eq("id", id);
    fetchSubmissions();
  }

  async function handleDelete(id) {
    if (!window.confirm("Delete this submission?")) return;
    await supabase.from("submissions").delete().eq("id", id);
    if (selected?.id === id) setSelected(null);
    flash("🗑 Submission deleted.");
    fetchSubmissions();
  }

  async function openSubmission(item) {
    setSelected(item);
    if (!item.read) {
      await supabase
        .from("submissions")
        .update({ read: true })
        .eq("id", item.id);
      fetchSubmissions();
    }
  }

  const unread = submissions.filter((s) => !s.read).length;

  return (
    <div>
      {/* Header */}
      <div className="flex items-center justify-between mb-6">
        <div>
          <h1 className="text-2xl font-extrabold text-[#0d1f3c] tracking-tight">
            Form Submissions
          </h1>
          <p className="text-slate-400 text-sm mt-1">
            {submissions.length} total ·{" "}
            <span className={unread > 0 ? "text-[#f26522] font-bold" : ""}>
              {unread} unread
            </span>
          </p>
        </div>
        {unread > 0 && (
          <div className="bg-[#f26522] text-white font-bold text-sm px-4 py-1.5 rounded-full">
            {unread} New
          </div>
        )}
      </div>

      {msg && (
        <div className="bg-green-50 border border-green-200 text-green-700 text-sm px-4 py-3 rounded-xl mb-5">
          {msg}
        </div>
      )}

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
        {/* List */}
        <div className="flex flex-col gap-3">
          {loading ? (
            <p className="text-slate-400 text-sm text-center py-10">
              Loading submissions...
            </p>
          ) : submissions.length === 0 ? (
            <div className="bg-white border-2 border-dashed border-slate-200 rounded-2xl p-12 text-center">
              <p className="text-4xl mb-3">📬</p>
              <p className="text-slate-500 font-medium">No submissions yet.</p>
            </div>
          ) : (
            submissions.map((s) => (
              <div key={s.id} onClick={() => openSubmission(s)}
                className={`bg-white border-2 rounded-2xl p-4 cursor-pointer transition-all hover:shadow-md ${
                  selected?.id === s.id
                    ? "border-[#f26522]"
                    : s.read
                    ? "border-slate-200"
                    : "border-[#f26522]/40 bg-orange-50/30"
                }`}>
                <div className="flex items-start justify-between gap-2">
                  <div className="flex-1 min-w-0">
                    <div className="flex items-center gap-2 mb-0.5">
                      {!s.read && (
                        <span className="w-2 h-2 bg-[#f26522] rounded-full flex-shrink-0" />
                      )}
                      <p className="text-[#0d1f3c] font-bold text-sm truncate">
                        {s.name}
                      </p>
                    </div>
                    <p className="text-slate-400 text-xs mb-1">{s.phone}</p>
                    <span className="inline-block bg-slate-100 text-slate-600 text-xs px-2 py-0.5 rounded-full">
                      {s.service}
                    </span>
                  </div>
                  <p className="text-slate-300 text-xs flex-shrink-0">
                    {new Date(s.created_at).toLocaleDateString()}
                  </p>
                </div>
              </div>
            ))
          )}
        </div>

        {/* Detail Panel */}
        <div className="bg-white border border-slate-200 rounded-2xl p-6 h-fit sticky top-6">
          {selected ? (
            <div>
              <div className="flex items-start justify-between mb-6">
                <div>
                  <h2 className="text-[#0d1f3c] font-extrabold text-lg">
                    {selected.name}
                  </h2>
                  <p className="text-slate-400 text-xs mt-0.5">
                    {new Date(selected.created_at).toLocaleString()}
                  </p>
                </div>
                <span className={`text-xs font-bold px-3 py-1 rounded-full ${
                  selected.read
                    ? "bg-slate-100 text-slate-500"
                    : "bg-orange-100 text-[#f26522]"
                }`}>
                  {selected.read ? "Read" : "Unread"}
                </span>
              </div>

              {[
                { label: "Phone / WhatsApp", value: selected.phone, icon: "📞" },
                { label: "Service Needed", value: selected.service, icon: "🛠" },
              ].map(({ label, value, icon }) => (
                <div key={label}
                  className="flex items-center gap-3 bg-slate-50 rounded-xl p-3 mb-3">
                  <span className="text-lg">{icon}</span>
                  <div>
                    <p className="text-xs text-slate-400 uppercase tracking-wider">
                      {label}
                    </p>
                    <p className="text-[#0d1f3c] font-semibold text-sm">{value}</p>
                  </div>
                </div>
              ))}

              <div className="bg-slate-50 rounded-xl p-4 mb-6">
                <p className="text-xs text-slate-400 uppercase tracking-wider mb-2">
                  Message
                </p>
                <p className="text-slate-700 text-sm leading-relaxed">
                  {selected.message}
                </p>
              </div>

              <div className="flex gap-3 flex-wrap">
                <a
                  href={`https://wa.me/233${selected.phone.replace(/^0/, "")}`}
                  target="_blank"
                  rel="noreferrer"
                  className="inline-flex items-center gap-2 bg-green-500 hover:bg-green-600 text-white font-bold text-sm px-4 py-2.5 rounded-full transition-all">
                  📱 WhatsApp
                </a>
                <button onClick={() => markRead(selected.id, selected.read)}
                  className="border-2 border-slate-200 hover:border-slate-400 text-slate-600 font-semibold text-sm px-4 py-2 rounded-full transition-all">
                  {selected.read ? "Mark Unread" : "Mark Read"}
                </button>
                <button onClick={() => handleDelete(selected.id)}
                  className="border-2 border-red-200 hover:border-red-400 text-red-500 font-semibold text-sm px-4 py-2 rounded-full transition-all">
                  🗑 Delete
                </button>
              </div>
            </div>
          ) : (
            <div className="text-center py-12">
              <p className="text-4xl mb-3">📬</p>
              <p className="text-slate-400 text-sm font-medium">
                Select a submission to view details
              </p>
            </div>
          )}
        </div>
      </div>
    </div>
  );
}
